@Composable fun CustomersScreen(vm: OperationsViewModel = hiltViewModel()) { var add by remember { mutableStateOf(false) }; LaunchedEffect(Unit) { vm.loadCustomers() }; Scaffold(topBar = { TopAppBar(title = { Text("Clientes") }, actions = { TextButton({ add = !add }) { Text(if (add) "Cerrar" else "Nuevo") } }) }) { p -> Column(Modifier.padding(p).padding(16.dp)) { if (add) CustomerForm { a, b, c, d -> vm.createCustomer(a, b, c, d); add = false }; if (vm.loading) LinearProgressIndicator(Modifier.fillMaxWidth()); vm.customers.forEach { CustomerRow(it) }; if (vm.customers.isEmpty() && !vm.loading) Text("Sin clientes", Modifier.padding(vertical = 24.dp)); vm.error?.let { Text(it, color = MaterialTheme.colorScheme.error) }; OutlinedButton({ vm.loadCustomers() }, Modifier.fillMaxWidth()) { Text("Actualizar") } } } }
@Composable fun ReceptionScreen(onCreated:()->Unit,vm:OperationsViewModel=hiltViewModel()){val scope=rememberCoroutineScope();var customerId by remember{mutableStateOf("")};var deviceId by remember{mutableStateOf("")};var branchId by remember{mutableStateOf("")};var summary by remember{mutableStateOf("")};var failure by remember{mutableStateOf("")};var checklist by remember{mutableStateOf("")};var promisedAt by remember{mutableStateOf(LocalDateTime.now().plusDays(1).withSecond(0).withNano(0).format(DateTimeFormatter.ofPattern("yyyy-MM-dd'T'HH:mm:ss")))};var priority by remember{mutableStateOf("NORMAL")};LaunchedEffect(Unit){vm.loadReceptionData()};LaunchedEffect(customerId){deviceId="";if(customerId.isNotBlank())vm.loadReceptionDevices(customerId)};Scaffold(topBar={TopAppBar(title={Text("Recepción de orden")})}){padding->LazyColumn(Modifier.padding(padding).padding(16.dp),verticalArrangement=Arrangement.spacedBy(10.dp)){item{Text("Cliente",style=MaterialTheme.typography.titleMedium);if(vm.customers.isEmpty())Text("No hay clientes cargados; registra el cliente primero en Clientes.");DropdownMenuField("Seleccionar cliente",vm.customers.map{(it.id.orEmpty()) to "${it.firstName.orEmpty()} ${it.lastName.orEmpty()}"},customerId){customerId=it}};if(customerId.isNotBlank())item{DropdownMenuField("Equipo (opcional)",listOf("" to "Sin equipo registrado")+vm.devices.map{(it.id.orEmpty()) to "${it.manufacturer.orEmpty()} ${it.model.orEmpty()} · ${it.serialNumber?:it.imei?:"sin serie"}"},deviceId){deviceId=it}};item{DropdownMenuField("Sucursal (opcional)",listOf("" to "Sucursal activa")+vm.branches.map{(it.id.orEmpty()) to it.name.orEmpty()},branchId){branchId=it}};item{OutlinedTextField(summary,{summary=it},Modifier.fillMaxWidth(),label={Text("Resumen / síntomas")})};item{OutlinedTextField(failure,{failure=it},Modifier.fillMaxWidth(),label={Text("Falla reportada")})};item{OutlinedTextField(checklist,{checklist=it},Modifier.fillMaxWidth(),label={Text("Checklist de recepción y accesorios")})};item{OutlinedTextField(promisedAt,{promisedAt=it},Modifier.fillMaxWidth(),label={Text("Compromiso (AAAA-MM-DDTHH:MM:SS)")})};item{DropdownMenuField("Prioridad",listOf("LOW" to "Baja","NORMAL" to "Normal","HIGH" to "Alta","URGENT" to "Urgente"),priority){priority=it}};item{Button({scope.launch{val job=vm.receiveOrder(customerId,deviceId.ifBlank{null},branchId.ifBlank{null},summary,failure,checklist,promisedAt,priority);job.join();if(vm.message=="Orden recibida correctamente")onCreated()}},enabled=!vm.loading&&customerId.isNotBlank()&&summary.isNotBlank()&&failure.isNotBlank()&&checklist.isNotBlank()&&promisedAt.isNotBlank(),modifier=Modifier.fillMaxWidth()){Text(if(vm.loading)"Guardando…" else "Crear orden")};vm.message?.let{Text(it,color=MaterialTheme.colorScheme.primary)};vm.error?.let{Text(it,color=MaterialTheme.colorScheme.error)}}}}}
@Composable private fun DropdownMenuField(label:String,options:List<Pair<String,String>>,selected:String,onSelect:(String)->Unit){var expanded by remember{mutableStateOf(false)};Box{OutlinedButton({expanded=true},Modifier.fillMaxWidth()){Text(options.firstOrNull{it.first==selected}?.second?:label)};DropdownMenu(expanded,{expanded=false}){options.forEach{(id,title)->DropdownMenuItem(text={Text(title)},onClick={onSelect(id);expanded=false})}}}}
@Composable private fun CustomerRow(x: Customer) = ListItem(headlineContent = { Text(listOfNotNull(x.firstName, x.lastName).joinToString(" ").ifBlank { "Cliente" }) }, supportingContent = { Text(x.email ?: x.phone ?: "Sin contacto") })
@Composable private fun CustomerForm(onSave: (String, String, String, String) -> Unit) { var first by remember { mutableStateOf("") }; var last by remember { mutableStateOf("") }; var email by remember { mutableStateOf("") }; var phone by remember { mutableStateOf("") }; Column { OutlinedTextField(first, { first = it }, Modifier.fillMaxWidth(), label = { Text("Nombre") }); OutlinedTextField(last, { last = it }, Modifier.fillMaxWidth(), label = { Text("Apellidos") }); OutlinedTextField(email, { email = it }, Modifier.fillMaxWidth(), label = { Text("Correo") }); OutlinedTextField(phone, { phone = it }, Modifier.fillMaxWidth(), label = { Text("Teléfono") }); Button({ onSave(first, last, email, phone) }, Modifier.fillMaxWidth(), enabled = first.isNotBlank() && last.isNotBlank()) { Text("Guardar cliente") } } }
@Composable fun InventoryScreen(vm: OperationsViewModel = hiltViewModel()) { LaunchedEffect(Unit) { vm.loadInventory() }; DataScreen("Inventario", vm.loading, vm.error, vm.inventory.isEmpty(), { vm.loadInventory() }) { vm.inventory.forEach { ListItem(headlineContent = { Text(it.name ?: it.sku ?: "Refacción") }, supportingContent = { Text("Existencia: ${it.quantity ?: 0}") }) } } }
@Composable fun OrderDetailScreen(id: String, vm: OperationsViewModel = hiltViewModel()) { var diagnosis by remember { mutableStateOf("") }; var workLog by remember { mutableStateOf("") }; var solution by remember { mutableStateOf("") }; var actionEvidence by remember { mutableStateOf("") }; var testName by remember { mutableStateOf("") }; var testPassed by remember { mutableStateOf(false) }; LaunchedEffect(id) { vm.loadOrder(id) }; Scaffold(topBar = { TopAppBar(title = { Text("Detalle de orden") }) }) { p -> LazyColumn(Modifier.padding(p).padding(16.dp)) { item { vm.selectedOrder?.let { order -> Text(order.orderNumber ?: order.id ?: "Orden", style = MaterialTheme.typography.headlineSmall); Text(order.status ?: "Sin estado"); Text(order.customerName ?: "Cliente pendiente"); Text(order.deviceDescription ?: "Equipo pendiente"); if(order.status=="QUOTED"){OutlinedTextField(actionEvidence,{actionEvidence=it},Modifier.fillMaxWidth(),label={Text("Evidencia / decisión del cliente")});Row { Button({ vm.orderAction(id,"authorize",actionEvidence) },enabled=actionEvidence.isNotBlank()&&!vm.loading) { Text("Autorizar") };Spacer(Modifier.width(8.dp));OutlinedButton({ vm.orderAction(id,"reject",actionEvidence) },enabled=actionEvidence.isNotBlank()&&!vm.loading){Text("Rechazar") } }}; OutlinedTextField(diagnosis, { diagnosis = it }, Modifier.fillMaxWidth(), label = { Text("Diagnóstico") }); OutlinedTextField(workLog, { workLog = it }, Modifier.fillMaxWidth(), label = { Text("Trabajo realizado") }); Button({ vm.updateOrder(id, "IN_PROGRESS", diagnosis, workLog) },enabled=!vm.loading&&diagnosis.isNotBlank()) { Text("Guardar diagnóstico") }; OutlinedTextField(solution, { solution = it }, Modifier.fillMaxWidth(), label = { Text("Solución") }); Button({ vm.quote(id, solution, 60, 0.0, 0.0, 0.0) }, enabled = solution.isNotBlank()&&!vm.loading) { Text("Guardar cotización") };if(order.status=="QA"){OutlinedTextField(actionEvidence,{actionEvidence=it},Modifier.fillMaxWidth(),label={Text("Nota de entrega")});OutlinedButton({vm.orderAction(id,"deliver",actionEvidence)},enabled=actionEvidence.isNotBlank()&&!vm.loading){Text("Entregar")}} }; Text("Timeline", style = MaterialTheme.typography.titleLarge) }; items(vm.timeline) { event -> ListItem(headlineContent = { Text(event.type ?: "Evento") }, supportingContent = { Text(event.description ?: "") }) }; item { Text("Pruebas de reparación", style = MaterialTheme.typography.titleLarge); OutlinedTextField(testName, { testName = it }, Modifier.fillMaxWidth(), label = { Text("Nombre de prueba") }); Row { Checkbox(checked = testPassed, onCheckedChange = { checked -> testPassed = checked }); Text("Aprobada") }; Button({ vm.addTest(id, testName, testPassed, ""); testName = "" }, enabled = testName.isNotBlank()&&!vm.loading) { Text("Registrar prueba") } }; items(vm.tests) { test -> ListItem(headlineContent = { Text(test.name ?: "Prueba") }, supportingContent = { Text(if (test.passed == true) "Aprobada" else "Pendiente") }) }; item { Text("Evidencias", style = MaterialTheme.typography.titleLarge); EvidencePicker(onSelected = { uri -> vm.addEvidence(id, "evidence-${System.currentTimeMillis()}", "image/*", uri.toString()) }) }; items(vm.evidence) { evidence -> ListItem(headlineContent = { Text(evidence.fileName ?: "Documento") }, supportingContent = { Text(evidence.contentType ?: "") }) }; vm.message?.let { message -> item { Text(message, color = MaterialTheme.colorScheme.primary) } }; vm.error?.let { errorMessage -> item { Text(errorMessage, color = MaterialTheme.colorScheme.error) } } } } }
@Composable private fun DataScreen(title: String, loading: Boolean, error: String?, empty: Boolean, retry: () -> Unit, content: @Composable ColumnScope.() -> Unit) { Scaffold(topBar = { TopAppBar(title = { Text(title) }) }) { p -> Column(Modifier.padding(p).padding(16.dp)) { if (loading) LinearProgressIndicator(modifier = Modifier.fillMaxWidth()); if (empty && !loading) Text("Sin información", modifier = Modifier.padding(vertical = 24.dp)); content(); error?.let { message: String -> Text(text = message, color = MaterialTheme.colorScheme.error, modifier = Modifier.padding(vertical = 12.dp)) }; OutlinedButton(onClick = retry, modifier = Modifier.fillMaxWidth()) { Text("Actualizar") } } } }
